from flask import Blueprint, request, jsonify, session, redirect
from services import (
    get_user_by_id,
    get_products_filtered,
    login_user,
    is_admin,
)

bp = Blueprint("main", __name__)

@bp.get("/health")
def health():
    """Health check endpoint."""
    return jsonify({"status": "ok"})


@bp.get("/users/<uid>")
def users(uid):
    """Retrieve a user by ID."""
    user = get_user_by_id(uid)
    if user:
        return jsonify(user)
    return jsonify({"error": "user_not_found"}), 404


@bp.get("/products")
def products():
    """List products with optional filtering."""
    q = request.args.get("q", "").lower().strip()
    c = request.args.get("category")
    items = get_products_filtered(q, c)
    return jsonify({"count": len(items), "items": items})


@bp.post("/login")
def login():
    """Authenticate a user and start a session."""
    data = request.get_json(silent=True) or {}
    user = login_user(data.get("user_id"))
    if not user:
        return jsonify({"error": "invalid_credentials"}), 401
    session["user_id"] = user["id"]
    return jsonify({"message": "logged_in", "user": user})


@bp.get("/me")
def me():
    """Return the current authenticated user."""
    uid = session.get("user_id")
    if not uid:
        return jsonify({"error": "not_authenticated"}), 401
    user = get_user_by_id(str(uid))
    if not user:
        return jsonify({"error": "user_not_found"}), 404
    return jsonify(user)


@bp.get("/admin")
def admin():
    """Admin-only endpoint."""
    uid = session.get("user_id")
    if not uid:
        return jsonify({"error": "not_authenticated"}), 401
    if not is_admin(uid):
        return jsonify({"error": "forbidden"}), 403
    return jsonify({"message": "admin_ok"})


@bp.get("/old-home")
def old_home():
    """Redirect legacy home to health endpoint."""
    return redirect("/health", 302)


def register_routes(app):
    """Register the blueprint with the Flask app."""
    app.register_blueprint(bp)
