from flask import Blueprint, request, jsonify, abort
from pydantic import ValidationError, BaseModel
from services import get_order, create_order, list_orders_service

order_bp = Blueprint('orders', __name__)

class Order(BaseModel):
    customer: str
    status: str

@order_bp.route('/health', methods=['GET'])
def health() -> dict:
    """Health check endpoint."""
    return jsonify({'status': 'ok'})

@order_bp.route('/orders/<int:oid>', methods=['GET'])
def get_order_route(oid: int) -> dict:
    """Retrieve a specific order by ID."""
    try:
        order = get_order(oid)
    except KeyError as exc:
        abort(404, description=str(exc))
    return jsonify(order)

@order_bp.route('/orders', methods=['POST'])
def create_order_route() -> dict:
    """Create a new order."""
    try:
        payload = request.get_json(force=True)
        order = Order.parse_obj(payload)
    except ValidationError as exc:
        return jsonify({'detail': exc.errors()}), 422
    created = create_order(order.dict())
    return jsonify(created)

@order_bp.route('/orders', methods=['GET'])
def list_orders_route() -> dict:
    """List orders, optionally filtered by status."""
    status = request.args.get('status')
    orders = list_orders_service(status)
    return jsonify({'count': len(orders), 'items': orders})

@order_bp.errorhandler(404)
def handle_not_found(error) -> dict:
    """Return JSON error for 404 responses."""
    return jsonify({'detail': error.description}), 404
